<script setup lang="ts">
import { reactive, watch } from 'vue'; import type { CreateProxyRequest, Proxy, UpdateProxyRequest } from '@/types'; import SurfaceDialog from '@/components/base/SurfaceDialog.vue'; import { DialogWidth } from '@/components/base/dialog'; import { ProxyFallbackMode, emptyProxyDraft, proxyDraftToRequest, proxyToDraft, type ProxyDraft } from '@/features/admin/resources/proxy'; import { useAppStore } from '@/stores/app'
const props = defineProps<{ show: boolean; proxy: Proxy | null; proxies: Proxy[]; submitting?: boolean }>(); const emit = defineEmits<{ close: []; submit: [payload: CreateProxyRequest | UpdateProxyRequest] }>(); const app = useAppStore(); const form = reactive<ProxyDraft>(emptyProxyDraft())
function submit(): void { try { const payload = proxyDraftToRequest(form, Boolean(props.proxy)); if (payload.backup_proxy_id === props.proxy?.id) throw new Error('备用代理不能选择自身'); emit('submit', payload) } catch (caught) { app.showError((caught as Error).message) } }
watch(() => props.show, (show) => { if (show) Object.assign(form, props.proxy ? proxyToDraft(props.proxy) : emptyProxyDraft()) })
</script>
<template><SurfaceDialog :show="show" :title="proxy ? '编辑代理' : '创建代理'" description="密码仅在主动填写时更新；空密码不会覆盖已有凭据。" :width="DialogWidth.WIDE" @close="emit('close')"><form id="proxy-editor-form" class="resource-form-stack" @submit.prevent="submit"><div class="resource-form-grid resource-form-grid--3"><label class="resource-field--wide">名称 *<input v-model="form.name" /></label><label>协议<select v-model="form.protocol"><option value="http">HTTP</option><option value="https">HTTPS</option><option value="socks5">SOCKS5</option><option value="socks5h">SOCKS5H</option></select></label><label>主机 *<input v-model="form.host" placeholder="127.0.0.1" /></label><label>端口 *<input v-model.number="form.port" type="number" min="1" max="65535" /></label><label>用户名<input v-model="form.username" autocomplete="off" /></label><label>密码 {{ proxy ? '（留空保持）' : '' }}<input v-model="form.password" type="password" autocomplete="new-password" /></label><label v-if="proxy">状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><label>到期时间<input v-model="form.expires_at" type="datetime-local" /></label><label>提前提醒天数<input v-model.number="form.expiry_warn_days" type="number" min="0" step="1" /></label><label>失效回退<select v-model="form.fallback_mode"><option :value="ProxyFallbackMode.NONE">不回退</option><option :value="ProxyFallbackMode.PROXY">切换备用代理</option><option :value="ProxyFallbackMode.DIRECT">直连</option></select></label><label v-if="form.fallback_mode === ProxyFallbackMode.PROXY">备用代理<select v-model="form.backup_proxy_id"><option value="">请选择</option><option v-for="item in proxies.filter(item => item.id !== proxy?.id)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.host }}</option></select></label></div></form><template #footer><button class="button button--secondary" @click="emit('close')">取消</button><button type="submit" form="proxy-editor-form" class="button button--primary" :disabled="submitting">{{ submitting ? '保存中…' : '保存代理' }}</button></template></SurfaceDialog></template>
